    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_phantom_protocol_fn_method_phantomlistener_verifying_key_bytes(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    companion object {
        
