    }
    
    class ConnectionClosed(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class Timeout(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Sliding-window replay protection rejected a packet. The AEAD layer
